394: std::vector<trace_command> trace_parser::parse_commandlist_file() {
395:   std::ifstream fs;
396:   fs.open(kernellist_filename);
397: 
398:   if (!fs.is_open()) {
399:     std::cerr << "Unable to open file: " << kernellist_filename << std::endl;
400:     exit(1);
401:   }
402: 
403:   std::string directory(kernellist_filename);
404:   const size_t last_slash_idx = directory.rfind('/');
405:   if (std::string::npos != last_slash_idx) {
406:     directory = directory.substr(0, last_slash_idx);
407:   }
408: 
409:   std::string line, filepath;
410:   std::vector<trace_command> commandlist;
411:   while (!fs.eof()) {
412:     getline(fs, line);
413:     if (line.empty())
414:       continue;
415:     else if (line.substr(0, 10) == "MemcpyHtoD") {
416:       trace_command command;
417:       command.command_string = line;
418:       command.m_type = command_type::cpu_gpu_mem_copy;
419:       commandlist.push_back(command);
420:     } else if (line.substr(0, 6) == "kernel") {
421:       trace_command command;
422:       command.m_type = command_type::kernel_launch;
423:       filepath = directory + "/" + line;
424:       command.command_string = filepath;
425:       commandlist.push_back(command);
426:     }
427:     // ignore gpu_to_cpu_memory_cpy
428:   }
429: 
430:   fs.close();
431:   return commandlist;
432: }
