434: void trace_parser::parse_memcpy_info(const std::string &memcpy_command,
435:                                      size_t &address, size_t &count) {
436:   std::vector<std::string> params;
437:   split(memcpy_command, params, ',');
438:   assert(params.size() == 3);
439:   std::stringstream ss;
440:   ss.str(params[1]);
441:   ss >> std::hex >> address;
442:   ss.clear();
443:   ss.str(params[2]);
444:   ss >> std::dec >> count;
445: }
